param([Parameter(Mandatory=$true)][ValidateSet('direct','group')][string]$TargetKind,[Parameter(Mandatory=$true)][string]$TargetId,[string]$Timezone='Asia/Shanghai',[string]$Agent='video-factory',[string]$ProjectRoot='E:\project\OpenClaw_VideoFactory',[switch]$Apply)
$ErrorActionPreference='Stop';$gate=Join-Path $ProjectRoot 'reports\gates\P2_READY.json';$factory=Join-Path $ProjectRoot 'scripts\factory.py';if(-not(Test-Path $factory)){throw 'factory.py missing.'};$text=Get-Content $factory -Raw;if($text -match 'production pipeline is not implemented'){throw 'Factory is fail-closed; complete P1/P2.'};if($Apply -and -not(Test-Path $gate)){throw "P2 gate missing: $gate"}
if($TargetKind -eq 'direct'){if($TargetId -notmatch '^ou_'){throw 'Direct ID must begin ou_.'};$to="user:$TargetId"}else{if($TargetId -notmatch '^oc_'){throw 'Group ID must begin oc_.'};$to="channel:$TargetId"}
$jobs=@(@{Name='video-topic-selection';Cron='30 8 * * *';Message="进入 $ProjectRoot。读取栏目配额、历史和来源，生成今日3到5个候选并发送飞书。只生成候选。"},@{Name='video-auto-select-and-produce';Cron='0 12 * * *';Message="进入 $ProjectRoot。若已有选择则制作；否则仅在评分、来源、去重和配额通过时选最高分并立即制作。质量通过后交付；不得发布抖音。"})
$logDir=Join-Path $ProjectRoot 'reports\cron';New-Item -ItemType Directory -Force -Path $logDir|Out-Null;$log=Join-Path $logDir ('register-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'.txt')
foreach($j in $jobs){$a=@('cron','add','--name',$j.Name,'--cron',$j.Cron,'--tz',$Timezone,'--session','isolated','--agent',$Agent,'--message',$j.Message,'--announce','--channel','feishu','--to',$to);('openclaw '+($a -join ' '))|Tee-Object -FilePath $log -Append;if($Apply){& openclaw @a 2>&1|Tee-Object -FilePath $log -Append;if($LASTEXITCODE -ne 0){throw "Failed $($j.Name)"}}};if(-not $Apply){Write-Host 'Dry run only. P2 gate required for -Apply.'}
